WHO = {'column': [('elsen', 103227), ('aprilicro', 103419), ('mugelllhdu', 103419), ('rodu', 0), ('zeflfeiel', 103675), ('alphafocgepy', 103675), ('mufoeiel', 0), ('alphafoldmicro', 0)], 'manor': [('qulfsof', 103419), ('bridlylglo', 103675), ('kavesen', 104315), ('kavior', 104635), ('kavesen', 0), ('qulfsof', 114936), ('bridlylglo', 115128), ('kavior', 116216)], 'tower': [('orgdmlgepy', 0), ('mugeyfrka', 105211), ('mugeysof', 113274), ('bridlylglo', 113530), ('mugeyfrka', 0), ('mugeysof', 116408)], 'tree': [('bridlyicro', 0), ('valecgepy', 0), ('kaveiva', 105595), ('aprilfools', 105595), ('bridlyicro', 105851), ('bridllhdu', 0), ('valecgepy', 106363), ('bridlyicro', 107067)], 'bridge': [('alphafoldmicro', 103803), ('alphafocgepy', 104315), ('mufoeiel', 105019), ('mufoeiel', 106555), ('alphafoldmicro', 0), ('mugelocgepy', 107771), ('alphafocgepy', 107771), ('alphafocgepy', 0)], 'temple': [('alphafocgepy', 0), ('alphafocgepy', 104699), ('einsof', 108987), ('orgdmyicro', 109755), ('einsof', 0), ('bridlyicro', 111931), ('orgdmyicro', 0), ('orgdmcgepy', 115384)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW87(OracleReleaseRuntimeW85):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
